unsafe fn run_Geno_ItemsSceneReset(seed: u64) -> [u64; 3] {
    rt::ST = seed; rt::MST = seed ^ 0x5DEECE66D; rt::TRACE = rt::FNV0; rt::REGS.truncate(rt::NSTATIC); rt::DYN.clear();
    fill_all();
    m::Geno_ItemsSceneReset();
    let ret = 0u64;
    let trace = rt::TRACE;
    hash_objs();
    let mut tot = rt::H;
    for h in rt::DYN.iter() { tot = rt::mix(tot, *h); }
    [ret, trace, tot]
}
